import urllib.request
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path: str) -> str:
        url = self.base_url + path
        headers = {
            'User-Agent': 'APIClient/1.0',
            'Accept': 'application/json'
        }

        # Retry logic for 429 (rate limit)
        rate_limit_retries = 3
        rate_limit_backoff = [0.5, 1.0, 2.0]
        for i in range(rate_limit_retries):
            try:
                req = urllib.request.Request(url, headers=headers)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    status = response.status
                    body = response.read().decode('utf-8')
                    if status == 429:
                        if i < rate_limit_retries - 1:
                            time.sleep(rate_limit_backoff[i])
                            continue
                        else:
                            raise RateLimitError(f"Rate limited after {rate_limit_retries} retries")
                    elif status >= 500 and status < 600:
                        # 5xx: retry once after 1s
                        time.sleep(1.0)
                        try:
                            req2 = urllib.request.Request(url, headers=headers)
                            with urllib.request.urlopen(req2, timeout=self.timeout) as response2:
