                        raise
                    except urllib.error.URLError:
                        raise ServerError("Server error after retry due to network issue")
                elif status >= 400 and status < 500:
                    if status == 429:
                        # Already handled above
                        if i < rate_limit_retries - 1:
                            time.sleep(rate_limit_backoff[i])
                            continue
                        else:
                            raise RateLimitError(f"Rate limited after {rate_limit_retries} retries")
                    else:
                        raise ClientError(f"Client error: {status}")
                else:
                    raise
            except urllib.error.URLError:
                # Network error: retry once after 1s
                time.sleep(1.0)
